const data = $input.first()?.json;

if (!data) {
  throw new Error("Groq response is missing.");
}

// Extract Groq Basic LLM Chain response
let raw =
  data.text ??
  data.output ??
  data.response ??
  data.content?.parts?.map(part => part.text || "").join("\n");

if (typeof raw !== "string" || !raw.trim()) {
  throw new Error("Groq returned an empty response.");
}

// Remove Markdown JSON fences
raw = raw
  .replace(/```json/gi, "")
  .replace(/```/g, "")
  .trim();

// Extract JSON object
const start = raw.indexOf("{");
const end = raw.lastIndexOf("}");

if (start === -1 || end <= start) {
  throw new Error("Valid JSON object not found in Groq response.");
}

let result;

try {
  result = JSON.parse(raw.substring(start, end + 1));
} catch (error) {
  throw new Error("Groq returned invalid JSON: " + error.message);
}

// Validate classification
const allowedCategories = [
  "Academics",
  "Examinations",
  "Hostel",
  "Transport",
  "Administration",
  "Other"
];

const allowedPriorities = [
  "Low",
  "Medium",
  "High",
  "Critical"
];

const allowedUrgencies = [
  "Normal",
  "Urgent"
];

if (!allowedCategories.includes(result.category)) {
  throw new Error("Invalid category returned by Groq.");
}

if (!allowedPriorities.includes(result.priority)) {
  throw new Error("Invalid priority returned by Groq.");
}

if (!allowedUrgencies.includes(result.urgency)) {
  throw new Error("Invalid urgency returned by Groq.");
}

if (
  typeof result.reason !== "string" ||
  !result.reason.trim()
) {
  throw new Error("Classification reason is missing.");
}

// Get original Supervisor input
const triggerData =
  $("When Executed by Another Workflow").first().json;

// Extract ticket code
const ticketCode =
  triggerData.context?.ticket_code ||
  triggerData.ticket_code;

if (!ticketCode || typeof ticketCode !== "string") {
  throw new Error("Ticket code missing from Supervisor input.");
}

// Return classification with ticket code
return [
  {
    json: {
      ticket_code: ticketCode,
      category: result.category,
      priority: result.priority,
      urgency: result.urgency,
      reason: result.reason.trim()
    }
  }
];
